/* cppi::219c8d1d5241c0039733774d8699c58754e2ac4684ab8cb51f09cd0aea42f319 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-05-20' and end_date = '2025-05-20')
and start_date = '2025-05-20' and end_date = '2025-05-20'

/* cppi::369f731b903e0d5a3daaa438006eff5c0ad102980f293405c01eaf7b35b63df4 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-06-03' and end_date = '2025-06-03')
and start_date = '2025-06-03' and end_date = '2025-06-03'

/* cppi::50892fa8292836b3419abdf5232652954f837c9dea4123c14c9e5662706faab8 */
select business_date, index_id, currency_code, market_value_base, weight, arrival_time
from (
        select *, max(arrival_time) over (partition by index_id, currency_code, business_date) max_publish
            from performance.production_sa_index_mix_by_currency
            where business_date between date '1989-07-31' and date '2025-04-01'
            and to_date(substring(cast(arrival_time as varchar), 1, 8), 'yyyymmdd') <= date '2025-04-01'
    ) a
where arrival_time = max_publish

