L END), 0)) > 1 THEN NULL ELSE SUM(CASE WHEN "analytic_type" = 'VOLATILITY_10YR' THEN "analytic_value" ELSE NULL END) / nullif(SUM(CASE WHEN "analytic_type" = 'PV' THEN "analytic_value" ELSE NULL END), 0) END) > 1 THEN NULL ELSE CASE WHEN ABS(SUM(CASE WHEN "analytic_type" = 'VOLATILITY_10YR' THEN "analytic_value" ELSE NULL END) / nullif(SUM(CASE WHEN "analytic_type" = 'PV' THEN "analytic_value" ELSE NULL END), 0)) > 1 THEN NULL ELSE SUM(CASE WHEN "analytic_type" = 'VOLATILITY_10YR' THEN "analytic_value" ELSE NULL END) / nullif(SUM(CASE WHEN "analytic_type" = 'PV' THEN "analytic_value" ELSE NULL END), 0) END END - (LAG(CASE WHEN ABS(CASE WHEN ABS(SUM(CASE WHEN "analytic_type" = 'VOLATILITY_10YR' THEN "analytic_value" ELSE NULL END) / nullif(SUM(CASE WHEN "analytic_type" = 'PV' THEN "analytic_value" ELSE NULL END), 0)) > 1 THEN NULL ELSE SUM(CASE WHEN "analytic_type" = 'VOLATILITY_10YR' THEN "analytic_value" ELSE NULL END) / nullif(SUM(CASE WHEN "analytic_type" = 'PV' THEN "analytic_value" ELSE NULL END), 0) END) > 1 THEN NULL ELSE CASE WHEN ABS(SUM(CASE WHEN "analytic_type" = 'VOLATILITY_10YR' THEN "analytic_value" ELSE NULL END) / nullif(SUM(CASE WHEN "analytic_type" = 'PV' THEN "analytic_value" ELSE NULL END), 0)) > 1 THEN NULL ELSE SUM(CASE WHEN "analytic_type" = 'VOLATILITY_10YR' THEN "analytic_value" ELSE NULL END) / nullif(SUM(CASE WHEN "analytic_type" = 'PV' THEN "analytic_value" ELSE NULL END), 0) END END) OVER (ORDER BY date_trunc('day', CAST(CAST(PARSE_DATETIME("business_date", 'yyyy-MM-dd') AS TIMESTAMP) AS TIMESTAMP)) NULLS FIRST)) AS "!calc.ba7f9b17-f530-4bc0-9ba6-691b4981ad9b.0.0"
FROM (SELECT business_date, hierarchy_level, account, portfolio_type, department, strategy, program, sub_program, analytic_value, tenor, curve_type, analytic_name, analytic_type, node_level,rating,currency,node
FROM "risk_prod"."rmv_analytics"
WHERE analytic_type IN ('DV01', 'PV', 'CS01', 'VOLATILITY_10YR','VAR_10YR')
  AND portfolio_type IN ('TOTAL_FUND_BY_ACCOUNT', 'IP')
  and (confidence_level is null or confidence_level = 0.95)
  AND (
    (analytic_type IN ('PV', 'VOLATILITY_10YR','VAR_10YR') AND hierarchy_level IN ('CPPIB-ALL', 'DEPARTMENT', 'ACCOUNT', 'POOL', 'STRATEGY', 'PROGRAM', 'SUB-PROGRAM'))
    OR (analytic_type IN ('CS01', 'DV01') AND hierarchy_level = 'MODEL_PORTFOLIO')
  )) AS "New custom SQL"
WHERE date_trunc('day', CAST(CAST(PARSE_DATETIME("business_date", 'yyyy-MM-dd') AS TIMESTAMP) AS TIMESTAMP)) = date_trunc('day', CAST(CAST(PARSE_DATETIME('2025-03-31 00:00:00', 'yyyy-MM-dd HH:mm:ss') AS TIMESTAMP) AS TIMESTAMP)) AND CASE WHEN "account" IS NULL AND "portfolio_type" = 'IP' THEN 'TOTAL FUND' ELSE "account" END IN ('ACPP') AND "analytic_type" IN ('VOLATILITY_10YR', 'PV')
GROUP BY date_trunc('day', CAST(CAST(PARSE_DATETIME("business_date", 'yyyy-MM-dd') AS TIMESTAMP) AS TIMESTAMP))
ORDER BY date_trunc('day', CAST(CAST(PARSE_DATETIME("business_date", 'yyyy-MM-dd') AS TIMESTAMP) AS TIMESTAMP)) DESC
LIMIT 2

